import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        System.out.println(new StringTokenizer(new String(System.in.readAllBytes())) instanceof StringTokenizer st && (Integer) Integer.parseInt(st.nextToken()) instanceof Integer n && (Integer) Integer.parseInt(st.nextToken()) instanceof Integer m && (Integer) Integer.parseInt(st.nextToken()) instanceof Integer w && new int[n] instanceof int[] wt && new int[n] instanceof int[] bt && new int[n] instanceof int[] p && new int[n] instanceof int[] sz && new int[n] instanceof int[] root && new int[w + 1] instanceof int[] dp && new IntUnaryOperator[1] instanceof IntUnaryOperator[] F && IntStream.range(0, n).map(i -> wt[i] = Integer.parseInt(st.nextToken())).max().isPresent() && IntStream.range(0, n).map(i -> bt[i] = Integer.parseInt(st.nextToken())).max().isPresent() && IntStream.range(0, n).map(i -> (sz[i] = 1) * 0 + (p[i] = i)).max().isPresent() && (F[0] = x -> p[x] == x ? x : F[0].applyAsInt(p[x])) instanceof IntUnaryOperator && IntStream.range(0, m).filter(e -> (Integer) F[0].applyAsInt(Integer.parseInt(st.nextToken()) - 1) instanceof Integer ra && (Integer) F[0].applyAsInt(Integer.parseInt(st.nextToken()) - 1) instanceof Integer rb && (ra.intValue() == rb.intValue() || (sz[ra] < sz[rb] ? ((p[ra] = rb) >= 0 & (sz[rb] += sz[ra]) > 0) : ((p[rb] = ra) >= 0 & (sz[ra] += sz[rb]) > 0)))).count() >= 0 && IntStream.range(0, n).map(i -> root[i] = F[0].applyAsInt(i)).max().isPresent() && IntStream.range(0, n).filter(r -> root[r] == r).filter(r -> IntStream.range(0, n).filter(i -> root[i] == r).toArray() instanceof int[] mem && (Integer) IntStream.of(mem).map(k -> wt[k]).sum() instanceof Integer sw && (Integer) IntStream.of(mem).map(k -> bt[k]).sum() instanceof Integer sb && IntStream.rangeClosed(0, w).map(j -> w - j).filter(j -> (dp[j] = Math.max(dp[j], Math.max(j >= sw ? dp[j - sw] + sb : 0, IntStream.of(mem).map(k -> j >= wt[k] ? dp[j - wt[k]] + bt[k] : 0).max().getAsInt()))) >= 0).count() >= 0).count() >= 0 ? dp[w] : 0);
    }
}
